select json_build_object(
'observed_at',now(),
'enums',(select coalesce(json_agg(statement order by statement),'[]'::json) from (select format('create type %I.%I as enum (%s);',n.nspname,t.typname,string_agg(quote_literal(e.enumlabel),',' order by e.enumsortorder)) statement from pg_type t join pg_namespace n on n.oid=t.typnamespace join pg_enum e on e.enumtypid=t.oid where n.nspname in ('public','app_private') group by n.nspname,t.typname) s),
'tables',(select json_agg(statement order by statement) from (select format('create table %I.%I (%s);',n.nspname,t.relname,string_agg(format('%I %s%s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),case when a.attidentity='a' then ' generated always as identity' when a.attidentity='d' then ' generated by default as identity' else '' end,case when a.attgenerated='s' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when a.attgenerated='v' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') virtual' when a.attidentity='' and a.attgenerated='' and d.adbin is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,case when a.attnotnull then ' not null' else '' end),',' order by a.attnum)) statement from pg_class t join pg_namespace n on n.oid=t.relnamespace join pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=t.oid and d.adnum=a.attnum where n.nspname in ('public','app_private') and t.relkind='r' group by n.nspname,t.relname) s),
'constraints',(select coalesce(json_agg(format('alter table %I.%I add constraint %I %s;',n.nspname,t.relname,c.conname,pg_get_constraintdef(c.oid)) order by c.conname),'[]'::json) from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname in ('public','app_private')),
'indexes',(select coalesce(json_agg(indexdef||';' order by indexname),'[]'::json) from pg_indexes where schemaname in ('public','app_private')),
'functions',(select coalesce(json_agg(pg_get_functiondef(p.oid) order by n.nspname,p.proname,p.oid),'[]'::json) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app_private') and p.prokind='f' and not exists (select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
'triggers',(select coalesce(json_agg(pg_get_triggerdef(tr.oid)||';' order by tr.tgname),'[]'::json) from pg_trigger tr join pg_class t on t.oid=tr.tgrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname in ('public','app_private') and not tr.tgisinternal),
'ledger',(select json_agg(row_to_json(m) order by version) from app_private.schema_migrations m)) as schema_snapshot;
